export const adv3Materials: AuthoredMaterial[] = [
  { id: "jee-adv-phy-kinematics-m01", topicId: "jee-adv-phy-kinematics", title: "Kinematics", content: `Motion is described by displacement, velocity, and acceleration. For **uniform acceleration**: v = u + at, s = ut + ½at², v² = u² + 2as, and s_nth = u + a(2n−1)/2. In **graphs**, the slope of x–t gives velocity, the slope of v–t gives acceleration, and the area under v–t gives displacement. **Projectile motion** resolves into independent horizontal (constant u cosθ) and vertical (under g) parts: time of flight 2u sinθ/g, max height u²sin²θ/2g, range u²sin2θ/g (max at 45°), and a parabolic path. **Relative velocity** v_AB = v_A − v_B solves river-boat and rain-man problems. In **circular motion**, centripetal acceleration is v²/r.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-phy-work-energy-power-m01", topicId: "jee-adv-phy-work-energy-power", title: "Work, Energy & Power", content: `**Work** W = F·d = Fd cosθ (zero when force ⟂ displacement). The **work–energy theorem**: net work = ΔKE. **Conservative forces** (gravity, spring) have path-independent work and an associated potential energy; **mechanical energy is conserved** when only conservative forces act. Spring PE = ½kx²; gravitational PE = mgh. **Power** P = W/t = F·v (SI unit watt). Non-conservative forces (friction) dissipate energy. In **collisions**, momentum is always conserved; kinetic energy is conserved only if elastic (coefficient of restitution e = 1). These principles handle loops, springs, and variable-force problems.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-phy-thermal-properties-m01", topicId: "jee-adv-phy-thermal-properties", title: "Thermal Properties & Calorimetry", content: `**Thermal expansion**: linear α, area β = 2α, volume γ = 3α. **Calorimetry**: heat Q = mcΔT for temperature change and Q = mL for phase change (latent heat, at constant temperature). Heat transfer occurs by **conduction** (rate = kAΔT/L), **convection**, and **radiation** (through vacuum). The **Stefan–Boltzmann law**: radiated power ∝ AT⁴; **Wien's law**: λ_max ∝ 1/T; **Newton's law of cooling**: cooling rate ∝ temperature difference. A **black body** is a perfect absorber and emitter. Water's high specific heat and anomalous expansion near 4 °C are notable. The principle of calorimetry: heat lost = heat gained.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-phy-elasticity-surface-tension-m01", topicId: "jee-adv-phy-elasticity-surface-tension", title: "Elasticity & Surface Tension", content: `**Stress** = force/area; **strain** = fractional deformation. Within the elastic limit, **Hooke's law** gives a modulus: **Young's** (Y, length), **bulk** (K, volume), and **shear** (η, shape). Elastic PE per volume = ½ × stress × strain. **Poisson's ratio** = lateral strain / longitudinal strain. **Surface tension** T (energy per area) minimises surface area; excess pressure is 2T/r (drop) and 4T/r (soap bubble). **Capillary rise** h = 2T cosθ/(ρgr) — liquids that wet (θ < 90°) rise, those that don't (mercury) fall. **Angle of contact** and the shapes of menisci follow from the balance of cohesive and adhesive forces.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-phy-semiconductors-m01", topicId: "jee-adv-phy-semiconductors", title: "Semiconductor Electronics", content: `**Intrinsic** semiconductors (pure Si, Ge) conduct weakly; **doping** creates extrinsic types: **n-type** (pentavalent donors → free electrons) and **p-type** (trivalent acceptors → holes). A **p–n junction** forms a depletion region and a barrier potential; it conducts in **forward bias** (barrier lowered) and blocks in **reverse bias** (used as a **rectifier**: half-wave and full-wave). A **Zener diode** works in reverse breakdown as a voltage regulator; an **LED** emits light on forward bias; a **photodiode** and **solar cell** convert light to current. A **transistor** (npn/pnp) amplifies or switches; **logic gates** (AND, OR, NOT, NAND, NOR) implement Boolean operations. Conduction rises with temperature (unlike metals).`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-chemical-bonding-m01", topicId: "jee-adv-chem-chemical-bonding", title: "Chemical Bonding & Hybridisation", content: `Bonds form to attain stability: **ionic** (electron transfer, lattice energy), **covalent** (sharing), and **coordinate** (both electrons from one atom). **VSEPR** predicts geometry from electron-pair repulsion (lone pairs repel more): linear, trigonal planar, tetrahedral, trigonal bipyramidal, octahedral. **Hybridisation**: sp (linear, 180°), sp² (trigonal, 120°), sp³ (tetrahedral, 109.5°), sp³d, sp³d². **Bond polarity and dipole moment** depend on electronegativity and geometry (CO₂ is non-polar despite polar bonds). **Hydrogen bonding** (H with F/O/N) and **Fajans' rules** (covalent character) explain many properties. MOT (bond order, paramagnetism) complements valence-bond ideas.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-periodicity-m01", topicId: "jee-adv-chem-periodicity", title: "Periodic Properties", content: `Periodic trends follow effective nuclear charge and shielding. **Atomic radius** decreases across a period, increases down a group; cations are smaller, anions larger than the parent atom. **Ionisation energy** increases across, decreases down (with dips at half/fully-filled subshells); successive IEs rise. **Electron affinity** is most negative for halogens (Cl > F due to small size). **Electronegativity** is highest for fluorine and increases across/up. The **diagonal relationship** (Li–Mg, Be–Al, B–Si) and the anomalous first member of each group arise from size and orbital differences. Metallic character increases down and to the left; non-metallic character the opposite.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-mole-concept-m01", topicId: "jee-adv-chem-mole-concept", title: "Mole Concept & Stoichiometry", content: `A **mole** = 6.022 × 10²³ particles = molar mass in grams = 22.4 L of gas at STP. **Moles = mass/molar mass = particles/Nₐ**. **Empirical formula** is the simplest ratio; the **molecular formula** is a whole multiple of it. **Stoichiometry** uses balanced equations; the **limiting reagent** is fully consumed and sets the yield (percentage yield = actual/theoretical × 100). Concentration terms: **molarity** (mol/L, T-dependent), **molality** (mol/kg), **mole fraction**, **normality** (gram-equivalents/L), and ppm. **Equivalent weight** and titration calculations (n-factor) and the ideal gas law tie the topic to volumetric analysis.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-redox-reactions-m01", topicId: "jee-adv-chem-redox-reactions", title: "Redox Reactions", content: `**Oxidation** is loss of electrons (↑ oxidation number); **reduction** is gain (↓). The **oxidising agent** is reduced; the **reducing agent** is oxidised (OIL RIG). Assign **oxidation numbers** by rules (O = −2 except peroxides/OF₂; H = +1 except hydrides; free element = 0; sum = charge). Balance redox equations by the **ion-electron (half-reaction) method** in acidic or basic media. **Disproportionation** oxidises and reduces the same element (e.g., Cl₂ + OH⁻). The **n-factor** (electrons exchanged) drives equivalent-weight and redox-titration calculations (KMnO₄, K₂Cr₂O₇, iodometry). Redox underlies electrochemistry, corrosion, and combustion.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-surface-chemistry-m01", topicId: "jee-adv-chem-surface-chemistry", title: "Surface Chemistry", content: `**Adsorption** accumulates species at a surface: **physisorption** (weak van der Waals, reversible, multilayer, low heat) vs **chemisorption** (strong bonds, specific, monolayer). Adsorption is exothermic; extent is described by the **Freundlich isotherm** (x/m = kp^(1/n)). **Catalysis** may be homogeneous or heterogeneous (adsorption theory); **enzymes** are highly specific biocatalysts. **Colloids** (1–1000 nm) show the **Tyndall effect** and **Brownian motion**; they are classified by phase (sol, gel, emulsion, aerosol) and affinity (lyophilic/lyophobic). Colloids are purified by **dialysis** and destabilised by adding electrolytes (**Hardy–Schulze rule**: higher ionic charge coagulates more strongly). Emulsions need emulsifiers.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-s-block-m01", topicId: "jee-adv-chem-s-block", title: "s-Block Elements", content: `**Group 1 (alkali metals**, ns¹) and **Group 2 (alkaline earth metals**, ns²) are reactive, low-ionisation-energy metals and strong reducing agents; reactivity increases down each group. They give characteristic **flame colours** (Na yellow, K lilac, Ca brick-red, Ba green). **Diagonal relationships**: Li–Mg and Be–Al. Key compounds: NaOH (chlor-alkali), Na₂CO₃·10H₂O (washing soda), NaHCO₃ (baking soda), CaO (quicklime), Ca(OH)₂ (slaked lime), CaSO₄·½H₂O (plaster of Paris), and CaOCl₂ (bleaching powder). Lithium and beryllium show anomalies (small size, covalent character); solubility and thermal-stability trends of their salts are common exam points.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-haloalkanes-haloarenes-m01", topicId: "jee-adv-chem-haloalkanes-haloarenes", title: "Haloalkanes & Haloarenes", content: `**Haloalkanes** undergo nucleophilic substitution: **SN1** (two-step via carbocation, favoured by 3° substrates and polar protic solvents, gives racemisation) and **SN2** (concerted, backside attack → inversion, favoured by 1° substrates, strong nucleophiles, and polar aprotic solvents). **Elimination** (E1/E2) competes, giving alkenes (Saytzeff product). **Haloarenes** are much less reactive to substitution because resonance gives the C–X bond **partial double-bond character**; nucleophilic aromatic substitution needs strong electron-withdrawing groups. Reactions with metals (Wurtz, Grignard), and the effects of substrate, nucleophile, and solvent, are core Advanced themes.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-amines-m01", topicId: "jee-adv-chem-amines", title: "Amines & Diazonium Salts", content: `**Amines** (R–NH₂) are ammonia derivatives, classed 1°/2°/3°. They are **basic** (N lone pair); in water, basicity order is influenced by inductive (+I raises), steric, and solvation effects, while **aniline is much weaker** (lone pair delocalised into the ring). Preparation: reduction of nitro compounds/nitriles, **Gabriel synthesis** (1° only), and **Hoffmann bromamide** (amide → amine, one fewer carbon). Amines react with HNO₂: aromatic 1° amines give **diazonium salts** (0–5 °C), versatile for **Sandmeyer**, coupling (azo dyes), and replacement reactions. The **carbylamine** and **Hinsberg** tests distinguish amine classes.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-biomolecules-polymers-m01", topicId: "jee-adv-chem-biomolecules-polymers", title: "Biomolecules & Polymers", content: `**Carbohydrates**: monosaccharides (glucose, fructose), disaccharides (sucrose — non-reducing; maltose, lactose), and polysaccharides (starch, cellulose, glycogen). **Proteins** are polymers of α-amino acids joined by **peptide bonds**, with primary–quaternary structure; **enzymes** are protein catalysts. **Nucleic acids** (DNA/RNA) store genetic information. **Vitamins** are fat-soluble (A, D, E, K) or water-soluble (B, C). **Polymers**: addition (polythene, PVC, Teflon) vs condensation (nylon-6,6, terylene, bakelite); classified as elastomers, fibres, thermoplastics, and thermosets. **Biodegradable** polymers (PHBV) address pollution. Reducing sugars, mutarotation, and the glycosidic bond are frequent exam points.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-math-indefinite-integration-m01", topicId: "jee-adv-math-indefinite-integration", title: "Indefinite Integration", content: `Integration reverses differentiation: ∫xⁿ dx = x^(n+1)/(n+1) + C (n ≠ −1), ∫(1/x)dx = ln|x| + C, ∫eˣ dx = eˣ + C, ∫sin x dx = −cos x + C. Core techniques: **substitution** (change of variable), **integration by parts** (∫u dv = uv − ∫v du, order by **ILATE**), **partial fractions** for rational functions, and **trigonometric substitutions/identities**. Standard forms include ∫dx/(x²+a²) = (1/a)tan⁻¹(x/a) and ∫dx/√(a²−x²) = sin⁻¹(x/a). Recognising the right method — and reducing an integrand to a standard form — is the essential Advanced skill.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-math-inverse-trigonometry-m01", topicId: "jee-adv-math-inverse-trigonometry", title: "Inverse Trigonometry", content: `Inverse trig functions invert the restricted trig functions. **Principal ranges**: sin⁻¹x ∈ [−π/2, π/2], cos⁻¹x ∈ [0, π], tan⁻¹x ∈ (−π/2, π/2). Key identities: **sin⁻¹x + cos⁻¹x = π/2**, tan⁻¹x + cot⁻¹x = π/2, sec⁻¹x + cosec⁻¹x = π/2. Addition formulas: tan⁻¹x + tan⁻¹y = tan⁻¹[(x+y)/(1−xy)] (with quadrant care). Domains: sin⁻¹/cos⁻¹ need |x| ≤ 1; sec⁻¹/cosec⁻¹ need |x| ≥ 1. These functions and their derivatives (d/dx sin⁻¹x = 1/√(1−x²)) recur throughout calculus and equation-solving.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-math-area-under-curves-m01", topicId: "jee-adv-math-area-under-curves", title: "Area Under Curves", content: `The **area under y = f(x)** from a to b (f ≥ 0) is ∫_a^b f(x)dx; where f < 0 the integral is negative, so take |f| or split at the x-axis crossings. **Area between two curves** is ∫(upper − lower)dx over their intersection, or ∫(right − left)dy when integrating in y. Symmetry (even/odd, about axes) simplifies computation. Standard results: area of the region bounded by y² = 4ax and its latus rectum, a circle, or an ellipse. Sketching the region first, finding intersection points, and choosing the convenient variable of integration are the keys to Advanced area problems.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-math-statistics-m01", topicId: "jee-adv-math-statistics", title: "Statistics & Mathematical Reasoning", content: `**Measures of central tendency**: mean, median, mode (empirically mode = 3median − 2mean). **Dispersion**: range, mean deviation, and **variance/standard deviation** (SD = √variance); variance = (Σx²/n) − (mean)². SD is unaffected by adding a constant but scales with multiplication. **Mathematical reasoning**: statements, negation, conjunction (∧), disjunction (∨), implication (→) and its **contrapositive** (equivalent) and converse. **De Morgan's laws**: ¬(p∧q) = ¬p∨¬q and ¬(p∨q) = ¬p∧¬q. Quantifiers (∀, ∃) and methods of proof (direct, contradiction, contrapositive, counterexample) complete the topic.`, estimatedReadTime: 2, orderIndex: 0 }
];

